param([Parameter(Mandatory=$true)][string]$MetricsPath,[Parameter(Mandatory=$true)][string]$FluidityPath,[Parameter(Mandatory=$true)][string]$RrPath,[Parameter(Mandatory=$true)][string]$LongHoldPath,[string]$MarkerIntegrityPath='',[Parameter(Mandatory=$true)][string]$OutPath)
$ErrorActionPreference='Stop'
function Read-Kv([string]$p){$h=@{};foreach($l in [IO.File]::ReadAllLines($p)){if($l -match '^([^=]+)=(.*)$'){$h[$matches[1].Trim()]=$matches[2].Trim()}};return $h}
$m=Read-Kv $MetricsPath;$f=Read-Kv $FluidityPath;$r=Read-Kv $RrPath;$h=Read-Kv $LongHoldPath;$mi=@{};if(-not [string]::IsNullOrWhiteSpace($MarkerIntegrityPath) -and (Test-Path -LiteralPath $MarkerIntegrityPath)){$mi=Read-Kv $MarkerIntegrityPath};$lines=New-Object 'System.Collections.Generic.List[string]';function Add([string]$k,[object]$v){$lines.Add($k+'='+[string]$v)};Add 'PTAR_PRESENTSHED1_PERCEPTUAL' '1';Add 'PRIORITY' 'PERCEIVED_FLUIDITY_FIRST';foreach($k in @('VISIBLE_FPS','ONE_PERCENT_LOW_EST_FPS','FRAME_INTERVAL_MEDIAN_MS','FRAME_INTERVAL_P95_MS','FRAME_INTERVAL_P99_MS','FRAME_INTERVAL_MAX_MS','FRAME_INTERVAL_CV_PCT','LONG_HOLDS_GT_1_5X_MEDIAN','LONG_HOLDS_GT_2X_MEDIAN','MICRO_BURSTS_LT_0_5X_MEDIAN')){if($m.ContainsKey($k)){Add $k $m[$k]}};foreach($k in @('VISIBLE_MULTIPLIER_VS_REAL','R_TO_R','G_TO_G','MAX_R_STREAK','TOTAL_DWELL_BALANCE_PCT','MEDIAN_DWELL_BALANCE_PCT')){if($f.ContainsKey($k)){Add $k $f[$k]}};foreach($k in @('RR_EPISODES','RR_WITH_G_READY_AFTER','RR_WITHOUT_G_READY_AFTER','RR_SNAPSHOT_UNAVAILABLE')){if($r.ContainsKey($k)){Add $k $r[$k]}};foreach($k in @('CLEAN_HOLDS_GE_50MS','CLEAN_HOLDS_GE_66MS','CLEAN_HOLDS_GE_100MS','CLEAN_HOLDS_GE_150MS','CLEAN_HOLDS_GE_200MS','REAL_HOLDS_GE_50MS','GENERATED_HOLDS_GE_50MS','MAX_CLEAN_HOLD_MS')){if($h.ContainsKey($k)){Add $k $h[$k]}};foreach($k in @('RAW_SERIAL_EXTRA_ADVANCES','PRESENT_CORROBORATED_MISSING_CONTENTS','MARKER_ONLY_EXTRA_ADVANCES','CLASSIFICATION')){if($mi.ContainsKey($k)){Add ('MARKER_'+$k) $mi[$k]}};Add 'INTERPRETATION' 'Perceived smoothness is primary. Long-hold events are the main diagnostic target; R/G alternation remains secondary.';[IO.File]::WriteAllLines($OutPath,$lines.ToArray(),(New-Object Text.UTF8Encoding($false)));exit 0
